-- Replace organization-wide SECURITY DEFINER reads with workspace filters.
create or replace function public.get_team_snapshot(p_organization_id uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_snapshot jsonb;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED' using errcode = '28000';
  end if;
  if private.organization_role_for(p_organization_id) is null then
    raise exception 'ORGANIZATION_ACCESS_DENIED' using errcode = '42501';
  end if;

  -- The high-water mark and rows are read by one statement under one MVCC
  -- snapshot. An event committed later will remain available to cursor pulls.
  with entities as (
    select 'workspace'::text as entity_type, w.id as entity_id,
      public.team_workspace_sync_payload(w.id) as payload
    from public.team_workspaces w where w.organization_id = p_organization_id and private.can_access_team_workspace(w.id)
    union all
    select 'task', t.id,
      jsonb_build_object('id', t.id, 'workspaceId', t.workspace_id,
        'externalId', t.external_id, 'title', t.title, 'description', t.description,
        'status', t.status, 'ownerId', t.owner_id, 'revisionSet', t.revision_set,
        'scope', t.scope, 'dependencies', t.dependencies, 'provenance', t.provenance,
        'version', t.version, 'updatedAt', t.updated_at)
    from public.team_tasks t join public.team_workspaces w on w.id = t.workspace_id
    where w.organization_id = p_organization_id and private.can_access_team_workspace(w.id)
    union all
    select 'decision', d.id,
      jsonb_build_object('id', d.id, 'workspaceId', d.workspace_id,
        'taskId', d.task_id, 'body', d.body, 'sourceRefs', d.source_refs,
        'supersedesId', d.supersedes_id,
        'createdBy', d.created_by, 'createdAt', d.created_at)
    from public.team_decisions d join public.team_workspaces w on w.id = d.workspace_id
    where w.organization_id = p_organization_id and private.can_access_team_workspace(w.id)
    union all
    select 'evidence', e.id,
      jsonb_build_object('id', e.id, 'workspaceId', e.workspace_id,
        'taskId', e.task_id, 'kind', e.kind, 'producer', e.producer,
        'revisionSet', e.revision_set, 'payload', e.payload,
        'createdBy', e.created_by, 'createdAt', e.created_at)
    from public.team_evidence e join public.team_workspaces w on w.id = e.workspace_id
    where w.organization_id = p_organization_id and private.can_access_team_workspace(w.id)
    union all
    select 'comment', c.id,
      jsonb_build_object('id', c.id, 'workspaceId', c.workspace_id,
        'taskId', c.task_id, 'body', c.body, 'createdBy', c.created_by,
        'createdAt', c.created_at)
    from public.team_comments c join public.team_workspaces w on w.id = c.workspace_id
    where w.organization_id = p_organization_id and private.can_access_team_workspace(w.id)
    union all
    select 'receipt', r.id,
      jsonb_build_object('id', r.id, 'workspaceId', r.workspace_id,
        'taskId', r.task_id, 'result', r.result, 'summary', r.summary,
        'revisionSet', r.revision_set, 'sourceRefs', r.source_refs,
        'createdBy', r.created_by, 'createdAt', r.created_at)
    from public.team_receipts r join public.team_workspaces w on w.id = r.workspace_id
    where w.organization_id = p_organization_id and private.can_access_team_workspace(w.id)
  ), bounded as (
    select * from entities order by entity_type, entity_id limit 10001
  )
  select jsonb_build_object(
    'cursor', greatest(
      (select coalesce(max(sequence), 0) from public.team_change_events
        where organization_id = p_organization_id),
      (select coalesce(floor_sequence, 0) from public.team_sync_floors
        where organization_id = p_organization_id)),
    'entities', coalesce(jsonb_agg(jsonb_build_object(
      'entityType', b.entity_type, 'entityId', b.entity_id, 'payload', b.payload)
      order by b.entity_type, b.entity_id), '[]'::jsonb))
  into v_snapshot from bounded b;
  if jsonb_array_length(v_snapshot -> 'entities') > 10000 then
    raise exception 'TEAM_SNAPSHOT_TOO_LARGE' using errcode = '54000';
  end if;
  return v_snapshot;
end;
$$;

create or replace function public.get_team_change_page(
  p_organization_id uuid, p_after bigint, p_limit integer default 100
)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  if private.organization_role_for(p_organization_id) is null then
    raise exception 'ORGANIZATION_ACCESS_DENIED' using errcode = '42501'; end if;
  if p_after < 0 or p_limit not between 1 and 100 then
    raise exception 'INVALID_CHANGE_CURSOR' using errcode = '22023'; end if;
  -- Floor and page are read under one MVCC snapshot, including during pruning.
  with floor as (
    select coalesce((select floor_sequence from public.team_sync_floors
      where organization_id = p_organization_id), 0) as sequence
  ), rows as (
    select e.* from public.team_change_events e
      where e.organization_id = p_organization_id and e.sequence > p_after
        and e.workspace_id is not null and private.can_access_team_workspace(e.workspace_id)
      order by e.sequence asc limit p_limit + 1
  ), page as (
    select * from rows order by sequence asc limit p_limit
  )
  select jsonb_build_object('expired', p_after < floor.sequence,
    'events', coalesce((select jsonb_agg(jsonb_build_object(
      'sequence', e.sequence, 'organization_id', e.organization_id,
      'workspace_id', e.workspace_id, 'operation_id', e.operation_id,
      'entity_type', e.entity_type, 'entity_id', e.entity_id,
      'event_type', e.event_type, 'payload', e.payload, 'created_at', e.created_at)
      order by e.sequence) from page e), '[]'::jsonb),
    'nextCursor', coalesce((select max(sequence) from page), p_after),
    'hasMore', (select count(*) > p_limit from rows))
    into v_result from floor;
  return v_result;
end;
$$;

create or replace function public.resolve_team_task_context(
  p_organization_id uuid, p_task_id uuid, p_limit integer default 25
)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  if private.organization_role_for(p_organization_id) is null then
    raise exception 'ORGANIZATION_ACCESS_DENIED' using errcode = '42501'; end if;
  if p_limit not between 1 and 50 then raise exception 'INVALID_CONTEXT_LIMIT' using errcode = '22023'; end if;
  select jsonb_build_object(
    'task', jsonb_build_object('id', t.id, 'externalId', t.external_id,
      'workspaceId', t.workspace_id, 'title', t.title, 'description', t.description,
      'status', t.status, 'ownerId', t.owner_id, 'revisionSet', t.revision_set,
      'scope', t.scope, 'dependencies', t.dependencies, 'provenance', t.provenance,
      'version', t.version, 'updatedAt', t.updated_at),
    'workspace', jsonb_build_object('id', w.id, 'name', w.name, 'organizationId', w.organization_id),
    'projects', coalesce((select jsonb_agg(jsonb_build_object('projectKey', p.project_key,
      'repository', p.repository, 'remoteUrl', p.remote_url, 'repositoryRoot', p.repository_root))
      from public.team_workspace_projects p where p.workspace_id = w.id), '[]'::jsonb),
    'unresolvedDependencies', coalesce((select jsonb_agg(dep.value)
      from jsonb_array_elements_text(t.dependencies) dep(value)
      where not exists (select 1 from public.team_tasks other
        where other.workspace_id = t.workspace_id and other.external_id = dep.value
          and other.status = 'completed')), '[]'::jsonb),
    'decisions', coalesce((select jsonb_agg(x.item order by x.created_at desc)
      from (select jsonb_build_object('id', d.id, 'body', d.body,
        'sourceRefs', d.source_refs, 'supersedesId', d.supersedes_id,
        'createdBy', d.created_by, 'createdAt', d.created_at) item, d.created_at
        from public.team_decisions d where d.task_id = t.id and not exists
          (select 1 from public.team_decisions newer where newer.supersedes_id = d.id)
        order by d.created_at desc limit p_limit) x), '[]'::jsonb),
    'comments', coalesce((select jsonb_agg(x.item order by x.created_at desc)
      from (select jsonb_build_object('id', c.id, 'body', c.body,
        'createdBy', c.created_by, 'createdAt', c.created_at) item, c.created_at
        from public.team_comments c where c.task_id = t.id
        order by c.created_at desc limit p_limit) x), '[]'::jsonb),
    'evidence', coalesce((select jsonb_agg(x.item order by x.created_at desc)
      from (select jsonb_build_object('id', e.id, 'kind', e.kind, 'producer', e.producer,
        'revisionSet', e.revision_set, 'payload', e.payload, 'createdBy', e.created_by,
        'createdAt', e.created_at, 'freshness', case when e.revision_set = t.revision_set
          then 'current' else 'stale' end) item, e.created_at
        from public.team_evidence e where e.task_id = t.id
        order by e.created_at desc limit p_limit) x), '[]'::jsonb),
    'receipts', coalesce((select jsonb_agg(x.item order by x.created_at desc)
      from (select jsonb_build_object('id', r.id, 'result', r.result,
        'summary', r.summary, 'revisionSet', r.revision_set,
        'sourceRefs', r.source_refs, 'createdBy', r.created_by,
        'createdAt', r.created_at, 'freshness', case when r.revision_set = t.revision_set
          then 'current' else 'stale' end) item, r.created_at
        from public.team_receipts r where r.task_id = t.id
        order by r.created_at desc limit p_limit) x), '[]'::jsonb),
    'resolvedAt', now(),
    'changeCursor', (select coalesce(max(sequence), 0) from public.team_change_events
      where organization_id = p_organization_id))
    into v_result from public.team_tasks t
    join public.team_workspaces w on w.id = t.workspace_id
    where t.id = p_task_id and w.organization_id = p_organization_id
      and private.can_access_team_workspace(w.id);
  if v_result is null then raise exception 'TASK_NOT_FOUND' using errcode = '42501'; end if;
  return v_result;
end;
$$;

create or replace function public.search_team_decisions(
  p_organization_id uuid, p_query text, p_limit integer default 25
)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_result jsonb;
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  if private.organization_role_for(p_organization_id) is null then
    raise exception 'ORGANIZATION_ACCESS_DENIED' using errcode = '42501'; end if;
  if char_length(trim(coalesce(p_query, ''))) not between 2 and 120
    or p_limit not between 1 and 50 then
    raise exception 'INVALID_DECISION_SEARCH' using errcode = '22023'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'workspaceId', x.workspace_id,
    'taskId', x.task_id, 'body', x.body, 'sourceRefs', x.source_refs,
    'createdBy', x.created_by, 'createdAt', x.created_at)
    order by x.created_at desc), '[]'::jsonb) into v_result
  from (select d.* from public.team_decisions d
    join public.team_workspaces w on w.id = d.workspace_id
    where w.organization_id = p_organization_id and private.can_access_team_workspace(w.id)
      and d.body ilike '%' || p_query || '%'
      and not exists (select 1 from public.team_decisions newer where newer.supersedes_id = d.id)
    order by d.created_at desc limit p_limit) x;
  return v_result;
end;
$$;
commit;

-- migration: 20261021190000_workspace_invitations.sql
-- A Team invitation grants membership in one workspace. Legacy account-only
-- invitations remain valid for compatibility, but new UI supplies workspace_id.
begin;
drop trigger enforce_team_seat_limit on public.organization_memberships;
alter table public.team_email_invitations add column workspace_id uuid;
alter table public.team_email_invitations add constraint team_invitation_workspace_org_fkey
  foreign key (organization_id,workspace_id)
  references public.team_workspaces(organization_id,id) on delete cascade;
alter table public.team_email_invitations drop constraint team_email_invitations_organization_id_email_key;
create unique index team_invitation_workspace_email_idx on public.team_email_invitations(workspace_id,email)
  where workspace_id is not null and accepted_at is null;
create unique index team_invitation_legacy_email_idx on public.team_email_invitations(organization_id,email)
  where workspace_id is null and accepted_at is null;

drop policy "team admins read invitations" on public.team_email_invitations;
create policy "workspace admins read invitations" on public.team_email_invitations
  for select to authenticated using (
    email=lower((select auth.jwt()->>'email')) or
    (workspace_id is not null and private.workspace_role_for(workspace_id) in ('owner','admin')) or
    (workspace_id is null and private.organization_role_for(organization_id) in ('owner','admin')));
drop policy "team admins create invitations" on public.team_email_invitations;
create policy "workspace admins create invitations" on public.team_email_invitations
  for insert to authenticated with check (
    invited_by=(select auth.uid()) and accepted_at is null and accepted_by is null and
    ((workspace_id is not null and private.workspace_role_for(workspace_id) in ('owner','admin')) or
     (workspace_id is null and private.organization_role_for(organization_id) in ('owner','admin'))));

create or replace function private.accept_team_email_invitation(p_invitation_id uuid)
returns uuid language plpgsql security definer set search_path = '' as $$
declare v_invitation public.team_email_invitations%rowtype;
  v_user_email text; v_confirmed timestamptz;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode='28000'; end if;
  select lower(email),email_confirmed_at into v_user_email,v_confirmed
    from auth.users where id=auth.uid();
  if v_user_email is null or v_confirmed is null then
    raise exception 'A confirmed email account is required' using errcode='42501'; end if;
  select * into v_invitation from public.team_email_invitations where id=p_invitation_id for update;
  if not found or v_invitation.email<>v_user_email then
    raise exception 'Invitation not found for this account' using errcode='42501'; end if;
  if v_invitation.accepted_at is not null or v_invitation.expires_at<=now() then
    raise exception 'Invitation has expired or was already accepted' using errcode='22023'; end if;
  insert into public.organization_memberships(organization_id,user_id,role)
    values(v_invitation.organization_id,auth.uid(),v_invitation.role)
    on conflict(organization_id,user_id) do nothing;
  if v_invitation.workspace_id is not null then
    insert into public.team_workspace_memberships(workspace_id,user_id,role)
      values(v_invitation.workspace_id,auth.uid(),v_invitation.role::text)
      on conflict(workspace_id,user_id) do nothing;
  end if;
  update public.team_email_invitations set accepted_at=now(),accepted_by=auth.uid()
    where id=p_invitation_id;
  return v_invitation.organization_id;
end;
$$;

create function private.enforce_team_workspace_seat_limit() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_limit integer; v_count integer;
begin
  if new.role='owner' then return new; end if;
  select seat_limit into v_limit from public.team_workspace_subscriptions
    where workspace_id=new.workspace_id for update;
  if v_limit is null then raise exception 'TEAM_ENTITLEMENT_MISSING' using errcode='42501'; end if;
  select count(*) into v_count from public.team_workspace_memberships
    where workspace_id=new.workspace_id;
  if v_count>=v_limit then raise exception 'TEAM_SEAT_LIMIT' using errcode='23514'; end if;
  return new;
end;
$$;
revoke all on function private.enforce_team_workspace_seat_limit() from public,anon,authenticated;
create trigger enforce_team_workspace_seat_limit before insert on public.team_workspace_memberships
  for each row execute function private.enforce_team_workspace_seat_limit();
create function public.remove_team_workspace_member(p_workspace_id uuid,p_user_id uuid)
returns boolean language plpgsql security definer set search_path = '' as $$
declare v_actor_role text; v_target_role text;
begin
  v_actor_role:=private.workspace_role_for(p_workspace_id);
  select role into v_target_role from public.team_workspace_memberships
    where workspace_id=p_workspace_id and user_id=p_user_id for update;
  if v_actor_role not in ('owner','admin') or v_target_role is null or
     v_target_role='owner' or (v_target_role='admin' and v_actor_role<>'owner') then
    raise exception 'WORKSPACE_MEMBERSHIP_CHANGE_DENIED' using errcode='42501';
  end if;
  delete from public.team_workspace_memberships
    where workspace_id=p_workspace_id and user_id=p_user_id;
  return true;
end;
$$;
revoke all on function public.remove_team_workspace_member(uuid,uuid) from public,anon;
grant execute on function public.remove_team_workspace_member(uuid,uuid) to authenticated;
commit;

-- migration: 20261021200000_workspace_source_policy.sql
-- Sharing choices are workspace-specific; account defaults are only copied
-- into existing workspaces during migration.
begin;
create table public.team_workspace_source_policies (
  workspace_id uuid primary key references public.team_workspaces(id) on delete cascade,
  sharing_mode text not null default 'metadata_only'
    check (sharing_mode in ('metadata_only','snippets','full_source')),
  updated_by uuid references auth.users(id) on delete set null,
  updated_at timestamptz not null default now()
);
insert into public.team_workspace_source_policies(workspace_id,sharing_mode,updated_by)
select w.id,coalesce(p.sharing_mode,'metadata_only'),p.updated_by
from public.team_workspaces w left join public.team_source_policies p on p.organization_id=w.organization_id;
create function private.initialize_team_workspace_source_policy() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.team_workspace_source_policies(workspace_id) values(new.id);
  return new;
end;
$$;
revoke all on function private.initialize_team_workspace_source_policy() from public,anon,authenticated;
create trigger a_initialize_team_workspace_source_policy after insert on public.team_workspaces
  for each row execute function private.initialize_team_workspace_source_policy();
alter table public.team_workspace_source_policies enable row level security;
create policy "members read workspace source policy" on public.team_workspace_source_policies
  for select to authenticated using(private.can_access_team_workspace(workspace_id));
create policy "workspace admins update source policy" on public.team_workspace_source_policies
  for update to authenticated
  using(private.workspace_role_for(workspace_id) in ('owner','admin'))
  with check(private.workspace_role_for(workspace_id) in ('owner','admin') and updated_by=(select auth.uid()));
grant select on public.team_workspace_source_policies to authenticated;
grant update(sharing_mode,updated_by,updated_at) on public.team_workspace_source_policies to authenticated;
revoke update(sharing_mode,updated_by,updated_at) on public.team_source_policies from authenticated;

create or replace function private.enforce_team_source_policy()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_mode text;
begin
  select sharing_mode into v_mode from public.team_workspace_source_policies
    where workspace_id=new.workspace_id;
  if v_mode is null then raise exception 'SOURCE_POLICY_MISSING' using errcode='42501'; end if;
  if v_mode='metadata_only' then
    if exists (select 1 from jsonb_object_keys(new.payload) as keys(key)
        where key not in ('summary','status','metrics','digest'))
      or char_length(coalesce(new.payload->>'summary',''))>1000
      or (new.payload ? 'metrics' and jsonb_typeof(new.payload->'metrics')<>'object')
      or char_length(new.payload::text)>4000 then
      raise exception 'SOURCE_SHARING_POLICY_DENIED' using errcode='42501'; end if;
  elsif v_mode='snippets' then
    if char_length(coalesce(new.payload->>'snippet',''))>4000 then
      raise exception 'SOURCE_SNIPPET_TOO_LARGE' using errcode='22023'; end if;
  end if;
  return new;
end;
$$;
commit;

-- migration: 20261021210000_team_project_binding_transaction.sql
-- GitHub rights are checked by the Worker immediately before this call. The
-- final service-role write rechecks AIPI membership in the same transaction,
-- so a concurrent workspace removal cannot authorize a stale binding.
begin;

create function public.bind_team_repository_project(
  p_actor_id uuid, p_workspace_id uuid, p_project_key text,
  p_provider_repository_id text, p_repository text,
  p_remote_url text, p_repository_root text
) returns jsonb language plpgsql set search_path = '' as $$
declare v_organization_id uuid;
  v_workspace_role text;
  v_organization_role text;
  v_existing_repository_id text;
  v_project public.team_workspace_projects%rowtype;
begin
  if current_user <> 'service_role' then
    raise exception 'PROJECT_BINDING_BROKER_REQUIRED' using errcode='42501';
  end if;
  select organization_id into v_organization_id from public.team_workspaces
    where id=p_workspace_id for update;
  if v_organization_id is null then
    raise exception 'WORKSPACE_UNAVAILABLE' using errcode='42501';
  end if;
  select role into v_workspace_role from public.team_workspace_memberships
    where workspace_id=p_workspace_id and user_id=p_actor_id for share;
  select role into v_organization_role from public.organization_memberships
    where organization_id=v_organization_id and user_id=p_actor_id for share;
  if v_workspace_role not in ('owner','admin','developer') or
     v_organization_role not in ('owner','admin','developer') or
     v_workspace_role is null or v_organization_role is null then
    raise exception 'WORKSPACE_WRITE_DENIED' using errcode='42501';
  end if;
  select provider_repository_id into v_existing_repository_id
    from public.team_workspace_projects
    where workspace_id=p_workspace_id and project_key=p_project_key for update;
  if v_existing_repository_id is not null and
     v_existing_repository_id<>p_provider_repository_id then
    raise exception 'PROJECT_REPOSITORY_CONFLICT' using errcode='40001';
  end if;
  insert into public.team_workspace_projects
    (workspace_id,project_key,provider,provider_repository_id,
     repository,remote_url,repository_root)
  values (p_workspace_id,p_project_key,'github',p_provider_repository_id,
    p_repository,p_remote_url,p_repository_root)
  on conflict (workspace_id,project_key) do update set
    provider='github',provider_repository_id=excluded.provider_repository_id,
    repository=excluded.repository,remote_url=excluded.remote_url,
    repository_root=excluded.repository_root,updated_at=now(),
    version=public.team_workspace_projects.version+1
  returning * into v_project;
  return to_jsonb(v_project);
end;
$$;
revoke all on function public.bind_team_repository_project(uuid,uuid,text,text,text,text,text)
  from public,anon,authenticated;
grant execute on function public.bind_team_repository_project(uuid,uuid,text,text,text,text,text)
  to service_role;

commit;

-- migration: 20261021220000_three_month_team_workspace_trial.sql
-- A workspace trial starts once, at workspace activation, and lasts three
-- calendar months in UTC. PostgreSQL month arithmetic clamps end-of-month
-- dates (January 31 -> April 30) while preserving the time of day.
begin;

create function private.team_trial_end(p_started_at timestamptz)
returns timestamptz language sql immutable strict set search_path = '' as $$
  select ((p_started_at at time zone 'UTC') + interval '3 months') at time zone 'UTC';
$$;
revoke all on function private.team_trial_end(timestamptz) from public, anon, authenticated;

alter table public.team_workspace_subscriptions
  add column trial_started_at timestamptz;

-- The earlier 14-day grant began when the workspace was created. Preserve
-- that activation time during upgrade rather than restarting the trial now.
update public.team_workspace_subscriptions as subscription
set trial_started_at = workspace.created_at,
    trial_ends_at = case when subscription.plan = 'trial'
      then private.team_trial_end(workspace.created_at)
      else subscription.trial_ends_at end
from public.team_workspaces as workspace
where workspace.id = subscription.workspace_id;

alter table public.team_workspace_subscriptions
  alter column trial_started_at set not null,
  alter column trial_started_at set default now();

create or replace function private.initialize_team_workspace_subscription()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.team_workspace_subscriptions
    (workspace_id, organization_id, trial_started_at, trial_ends_at)
  values (new.id, new.organization_id, new.created_at,
    private.team_trial_end(new.created_at));
  return new;
end;
$$;
revoke all on function private.initialize_team_workspace_subscription() from public, anon, authenticated;

commit;

-- migration: 20261022230000_broker_team_graph_reads.sql
-- GitHub-bound graph source references must not be readable through direct
-- PostgREST table access: workspace membership cannot prove a live GitHub
-- user grant. The Team worker brokers bounded graph reads and rechecks grants.
begin;
revoke select on public.team_graph_nodes, public.team_graph_edges from authenticated;
grant select on public.team_graph_nodes, public.team_graph_edges to service_role;
grant select on public.team_ci_receipts, public.team_workspaces,
  public.team_workspace_memberships, public.organization_memberships,
  public.team_workspace_projects to service_role;
