  public.organization_memberships to service_role;
commit;

-- migration: 20261022231000_broker_team_graph_writes.sql
-- A workspace editor may publish/review a GitHub-bound graph only through the
-- Worker after a current user + App repository check. Recheck AIPI roles under
-- row locks in the service transaction so removal wins over queued work.
begin;
grant usage on schema private to service_role;

revoke execute on function public.publish_team_graph(uuid,jsonb,jsonb) from authenticated;
revoke execute on function public.review_team_graph_edge(uuid,boolean) from authenticated;
grant execute on function public.publish_team_graph(uuid,jsonb,jsonb) to service_role;
grant execute on function public.review_team_graph_edge(uuid,boolean) to service_role;

create function private.assert_team_graph_editor(p_actor_id uuid,p_workspace_id uuid)
returns void language plpgsql set search_path = '' as $$
declare v_organization_id uuid; v_workspace_role text; v_organization_role text;
begin
  if current_user <> 'service_role' then
    raise exception 'GRAPH_BROKER_REQUIRED' using errcode='42501';
  end if;
  select organization_id into v_organization_id from public.team_workspaces
    where id=p_workspace_id for update;
  if v_organization_id is null then raise exception 'WORKSPACE_UNAVAILABLE' using errcode='42501'; end if;
  select role into v_workspace_role from public.team_workspace_memberships
    where workspace_id=p_workspace_id and user_id=p_actor_id for share;
  select role into v_organization_role from public.organization_memberships
    where organization_id=v_organization_id and user_id=p_actor_id for share;
  if v_workspace_role not in ('owner','admin','developer') or
     v_organization_role not in ('owner','admin','developer') or
     v_workspace_role is null or v_organization_role is null then
    raise exception 'WORKSPACE_WRITE_DENIED' using errcode='42501';
  end if;
end;
$$;
revoke all on function private.assert_team_graph_editor(uuid,uuid) from public,anon,authenticated;
grant execute on function private.assert_team_graph_editor(uuid,uuid) to service_role;

create function public.broker_publish_team_graph(
  p_actor_id uuid,p_workspace_id uuid,p_nodes jsonb,p_edges jsonb
) returns jsonb language plpgsql set search_path = '' as $$
declare v_previous_sub text; v_result jsonb;
begin
  perform private.assert_team_graph_editor(p_actor_id,p_workspace_id);
  v_previous_sub := current_setting('request.jwt.claim.sub',true);
  perform set_config('request.jwt.claim.sub',p_actor_id::text,true);
  v_result := public.publish_team_graph(p_workspace_id,p_nodes,p_edges);
  perform set_config('request.jwt.claim.sub',coalesce(v_previous_sub,''),true);
  return v_result;
end;
$$;
revoke all on function public.broker_publish_team_graph(uuid,uuid,jsonb,jsonb)
  from public,anon,authenticated;
grant execute on function public.broker_publish_team_graph(uuid,uuid,jsonb,jsonb) to service_role;

create function public.broker_review_team_graph_edge(
  p_actor_id uuid,p_workspace_id uuid,p_edge_id uuid,p_confirm boolean
) returns jsonb language plpgsql set search_path = '' as $$
declare v_previous_sub text; v_result jsonb;
begin
  perform private.assert_team_graph_editor(p_actor_id,p_workspace_id);
  if not exists(select 1 from public.team_graph_edges
    where id=p_edge_id and workspace_id=p_workspace_id) then
    raise exception 'GRAPH_EDGE_UNAVAILABLE' using errcode='42501';
  end if;
  v_previous_sub := current_setting('request.jwt.claim.sub',true);
  perform set_config('request.jwt.claim.sub',p_actor_id::text,true);
  v_result := public.review_team_graph_edge(p_edge_id,p_confirm);
  perform set_config('request.jwt.claim.sub',coalesce(v_previous_sub,''),true);
  return v_result;
end;
$$;
revoke all on function public.broker_review_team_graph_edge(uuid,uuid,uuid,boolean)
  from public,anon,authenticated;
grant execute on function public.broker_review_team_graph_edge(uuid,uuid,uuid,boolean) to service_role;

commit;

-- migration: 20261022232000_lock_workspace_writer_membership.sql
-- Serialize workspace-scoped writes with membership removal. A queued write
-- that acquires these row locks after revocation must fail; if it acquires
-- them first, revocation waits until the write commits.
begin;
-- The repository-binding broker runs as service_role and locks/updates the
-- project row. Grant its table operations explicitly for minimal deployments.
grant select,insert,update on public.team_workspace_projects to service_role;
create or replace function private.guard_team_workspace_scoped_write() returns trigger
language plpgsql security definer set search_path = '' as $$
declare v_actor uuid := (select auth.uid()); v_workspace_id uuid;
begin
  if v_actor is null then
    if (select auth.role()) = 'service_role' then
      if tg_op = 'DELETE' then return old; else return new; end if;
    end if;
    raise exception 'AUTH_REQUIRED' using errcode='28000';
  end if;
  v_workspace_id := case when tg_op = 'DELETE' then old.workspace_id else new.workspace_id end;
  perform 1 from public.team_workspace_memberships wm
    join public.team_workspaces w on w.id = wm.workspace_id
    join public.organization_memberships om on om.organization_id = w.organization_id
      and om.user_id = wm.user_id
    where wm.workspace_id = v_workspace_id and wm.user_id = v_actor
      and wm.role in ('owner','admin','developer')
      and om.role in ('owner','admin','developer')
    for share of wm,w,om;
  if not found then raise exception 'WORKSPACE_WRITE_DENIED' using errcode='42501'; end if;
  if tg_op = 'UPDATE' and old.workspace_id is distinct from new.workspace_id then
    perform 1 from public.team_workspace_memberships wm
      join public.team_workspaces w on w.id = wm.workspace_id
      join public.organization_memberships om on om.organization_id = w.organization_id
        and om.user_id = wm.user_id
      where wm.workspace_id = old.workspace_id and wm.user_id = v_actor
        and wm.role in ('owner','admin','developer')
        and om.role in ('owner','admin','developer')
      for share of wm,w,om;
    if not found then raise exception 'WORKSPACE_WRITE_DENIED' using errcode='42501'; end if;
  end if;
  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$$;
revoke all on function private.guard_team_workspace_scoped_write() from public,anon,authenticated;
commit;

-- migration: 20261023010000_workspace_source_identities.sql
begin;
-- Portable identities only. Device paths, checkout credentials and secrets
-- have no columns in these tables.
create table public.team_workspace_repositories (
  workspace_id uuid not null references public.team_workspaces(id) on delete cascade,
  provider_repository_id text not null check(provider_repository_id ~ '^[1-9][0-9]{0,29}$'),
  provider text not null default 'github' check(provider='github'),
  repository text not null check(char_length(repository) between 1 and 240),
  remote_url text not null check(remote_url ~ '^https://github[.]com/[^/]+/[^/]+$'),
  primary key(workspace_id,provider_repository_id)
);
create table public.team_source_bindings (
  workspace_id uuid not null,
  project_key text not null,
  source_id text not null check(source_id ~ '^src_[A-Za-z0-9_-]{8,100}$'),
  name text not null check(char_length(name) between 1 and 120),
  kind text not null check(kind in ('local','repository','external')),
  provider_repository_id text,
  repository_root text not null default '.' check(repository_root='.' or (repository_root ~ '^[A-Za-z0-9_.-]+(/[A-Za-z0-9_.-]+)*$' and repository_root !~ '(^|/)[.]{1,2}(/|$)')),
  external_endpoint text check(external_endpoint ~ '^https://[^/@?#]+([/][^?#]*)?$'),
  version bigint not null default 1 check(version>0),
  primary key(workspace_id,source_id),
  foreign key(workspace_id,project_key) references public.team_workspace_projects(workspace_id,project_key) on delete cascade,
  foreign key(workspace_id,provider_repository_id) references public.team_workspace_repositories(workspace_id,provider_repository_id),
  check((kind='repository')=(provider_repository_id is not null)),
  check((kind='external')=(external_endpoint is not null))
);
create index team_source_project_idx on public.team_source_bindings(workspace_id,project_key);
alter table public.team_source_bindings enable row level security;
alter table public.team_workspace_repositories enable row level security;
create policy source_identity_read on public.team_source_bindings for select to authenticated using(private.can_access_team_workspace(workspace_id));
create policy repository_identity_read on public.team_workspace_repositories for select to authenticated using(private.can_access_team_workspace(workspace_id));
grant select on public.team_source_bindings,public.team_workspace_repositories to authenticated;
grant all on public.team_source_bindings,public.team_workspace_repositories to service_role;

-- Preserve the existing project binding API as the primary-source adapter.
create function private.mirror_primary_source() returns trigger language plpgsql security definer set search_path='' as $$
begin
  if new.provider_repository_id is not null then
    insert into public.team_workspace_repositories(workspace_id,provider_repository_id,repository,remote_url)
      values(new.workspace_id,new.provider_repository_id,new.repository,new.remote_url)
      on conflict(workspace_id,provider_repository_id) do update set repository=excluded.repository,remote_url=excluded.remote_url;
  end if;
  insert into public.team_source_bindings(workspace_id,project_key,source_id,name,kind,provider_repository_id,repository_root,version)
    values(new.workspace_id,new.project_key,'src_'||substr(md5('aipi:primary:'||new.project_key),1,24),left(coalesce(new.repository,new.project_key),120),
      case when new.provider_repository_id is null then 'local' else 'repository' end,new.provider_repository_id,coalesce(new.repository_root,'.'),new.version)
    on conflict(workspace_id,source_id) do update set kind=excluded.kind,provider_repository_id=excluded.provider_repository_id,
      repository_root=excluded.repository_root,version=excluded.version;
  return new;
end $$;
revoke all on function private.mirror_primary_source() from public;
create trigger mirror_primary_source after insert or update on public.team_workspace_projects for each row execute function private.mirror_primary_source();
insert into public.team_workspace_repositories(workspace_id,provider_repository_id,repository,remote_url)
 select distinct on(workspace_id,provider_repository_id) workspace_id,provider_repository_id,repository,remote_url
 from public.team_workspace_projects where provider_repository_id is not null;
insert into public.team_source_bindings(workspace_id,project_key,source_id,name,kind,provider_repository_id,repository_root,version)
 select workspace_id,project_key,'src_'||substr(md5('aipi:primary:'||project_key),1,24),left(coalesce(repository,project_key),120),
 case when provider_repository_id is null then 'local' else 'repository' end,provider_repository_id,coalesce(repository_root,'.'),version
 from public.team_workspace_projects;

