  if not found then raise exception 'PROJECT_UNAVAILABLE' using errcode='23503';end if;
 else
  v_result=public.bind_team_project_source(p_actor_id,p_workspace_id,p_project_key,p_source_id,p_name,p_kind,p_provider_repository_id,
   p_repository,p_remote_url,p_repository_root,p_external_endpoint,p_expected_version);
  select * into v_source from public.team_source_bindings where workspace_id=p_workspace_id and source_id=v_result->>'source_id';
 end if;
 -- A repeated request for the same repository must not retarget an existing branch silently.
 if v_source.source_id<>p_source_id and v_source.tracking_branch is not null and v_source.tracking_branch is distinct from p_tracking_branch then
  raise exception 'SOURCE_ALREADY_CONNECTED_SELECT_EXISTING' using errcode='40001';end if;
 update public.team_source_bindings set version=version+case when tracking_branch is distinct from p_tracking_branch or tracking_commit is distinct from p_tracking_commit then 1 else 0 end,tracking_branch=p_tracking_branch,tracking_commit=p_tracking_commit
  where workspace_id=p_workspace_id and source_id=v_source.source_id returning * into v_source;
 return to_jsonb(v_source);
end $$;
commit;

-- migration: 20261023030000_graph_review_operations.sql
-- Review retries must not overwrite a later review. The Worker brokers current
-- source grants; this RPC serializes the graph write and its durable receipt.
begin;

alter table public.team_graph_edges add column version bigint not null default 1
  check (version > 0);

create function public.broker_review_team_graph_edge_operation(
  p_actor_id uuid, p_workspace_id uuid, p_device_id uuid,
  p_operation_id uuid, p_edge_id uuid, p_confirm boolean, p_base_version bigint
) returns jsonb language plpgsql set search_path = '' as $$
declare
  v_organization_id uuid;
  v_fingerprint text;
  v_existing public.team_accepted_operations%rowtype;
  v_edge public.team_graph_edges%rowtype;
begin
  perform private.assert_team_graph_editor(p_actor_id, p_workspace_id);
  select organization_id into v_organization_id from public.team_workspaces
    where id = p_workspace_id;
  if p_operation_id is null or p_device_id is null or p_edge_id is null or
     p_confirm is null or p_base_version is null or p_base_version < 1 then
    raise exception 'INVALID_GRAPH_REVIEW_OPERATION' using errcode = '22023';
  end if;
  if not exists (select 1 from public.team_devices d where d.id = p_device_id
    and d.organization_id = v_organization_id and d.user_id = p_actor_id
    and d.revoked_at is null) then
    raise exception 'DEVICE_REVOKED_OR_UNKNOWN' using errcode = '42501';
  end if;
  v_fingerprint := pg_catalog.md5(p_workspace_id::text || ':' ||
    p_edge_id::text || ':' || p_confirm::text || ':' || p_base_version::text);
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_organization_id::text, 0));
  select * into v_existing from public.team_accepted_operations a
    where a.organization_id = v_organization_id
      and a.operation_id = p_operation_id for update;
  if found then
    if v_existing.actor_id <> p_actor_id or v_existing.device_id <> p_device_id or
       v_existing.request_fingerprint is distinct from v_fingerprint or
       v_existing.ack_entity_type <> 'graph_edge' or
       v_existing.ack_entity_id <> p_edge_id then
      raise exception 'OPERATION_ID_REUSED' using errcode = '40001';
    end if;
    return pg_catalog.jsonb_build_object('id', p_edge_id,
      'confirmationState', case when p_confirm then 'confirmed' else 'rejected' end,
      'version', v_existing.ack_version, 'operationId', p_operation_id,
      'wasDuplicate', true);
  end if;

  select * into v_edge from public.team_graph_edges e
    where e.id = p_edge_id and e.workspace_id = p_workspace_id for update;
  if not found then raise exception 'GRAPH_EDGE_UNAVAILABLE' using errcode = '42501'; end if;
  if v_edge.version <> p_base_version then
    raise exception 'GRAPH_REVIEW_VERSION_CONFLICT' using errcode = '40001';
  end if;
  if exists (select 1 from public.team_graph_nodes n
    where n.id in (v_edge.from_node_id, v_edge.to_node_id)
      and not exists (select 1 from pg_catalog.jsonb_array_elements(v_edge.revision_set) pin
        where pin ->> 'projectKey' = n.project_key and
          pin ->> 'commit' = n.revision_commit)) then
    raise exception 'GRAPH_REVIEW_STALE_REVISION' using errcode = '40001';
  end if;
  update public.team_graph_edges set
    confirmation_state = case when p_confirm then 'confirmed' else 'rejected' end,
    reviewed_by = p_actor_id, reviewed_at = now(), version = version + 1
    where id = p_edge_id returning * into v_edge;
  insert into public.team_accepted_operations
    (organization_id, device_id, operation_id, actor_id,
     request_fingerprint, ack_entity_type, ack_entity_id, ack_version)
    values (v_organization_id, p_device_id, p_operation_id, p_actor_id,
      v_fingerprint, 'graph_edge', p_edge_id, v_edge.version);
  return pg_catalog.jsonb_build_object('id', p_edge_id,
    'confirmationState', v_edge.confirmation_state, 'version', v_edge.version,
    'operationId', p_operation_id, 'wasDuplicate', false);
end;
$$;

revoke all on function public.broker_review_team_graph_edge(uuid,uuid,uuid,boolean)
  from public, anon, authenticated, service_role;
revoke all on function public.review_team_graph_edge(uuid,boolean)
  from public, anon, authenticated, service_role;
revoke all on function public.broker_review_team_graph_edge_operation(uuid,uuid,uuid,uuid,uuid,boolean,bigint)
  from public, anon, authenticated;
grant execute on function public.broker_review_team_graph_edge_operation(uuid,uuid,uuid,uuid,uuid,boolean,bigint)
  to service_role;

commit;

-- migration: 20261023031000_source_aware_revision_guards.sql
-- New revision claims must resolve to the source they describe. Historical
-- rows are left intact; edits that retain their old revision set stay valid.
begin;

create function private.validate_team_revision_set(p_workspace_id uuid, p_revisions jsonb)
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_revision jsonb;
  v_source_count integer;
begin
  if p_revisions is null or pg_catalog.jsonb_typeof(p_revisions) <> 'array' or
     pg_catalog.jsonb_array_length(p_revisions) > 32 then
    raise exception 'INVALID_REVISION_SET' using errcode = '22023';
  end if;
  for v_revision in select value from pg_catalog.jsonb_array_elements(p_revisions) loop
    if pg_catalog.jsonb_typeof(v_revision) <> 'object' or
       exists (select 1 from pg_catalog.jsonb_object_keys(v_revision) as field(key)
         where key not in ('projectKey', 'sourceBindingId', 'commit')) or
       coalesce(v_revision ->> 'projectKey', '') !~ '^prj_[A-Za-z0-9_-]{4,100}$' or
       coalesce(v_revision ->> 'commit', '') !~ '^[a-f0-9]{40}$' or
       not exists (select 1 from public.team_workspace_projects p
         where p.workspace_id = p_workspace_id and p.project_key = v_revision ->> 'projectKey') then
      raise exception 'INVALID_SOURCE_REVISION' using errcode = '22023';
    end if;
    if v_revision ? 'sourceBindingId' then
      if coalesce(v_revision ->> 'sourceBindingId', '') !~ '^src_[A-Za-z0-9_-]{8,100}$' or
         not exists (select 1 from public.team_source_bindings s
           where s.workspace_id = p_workspace_id and
             s.project_key = v_revision ->> 'projectKey' and
             s.source_id = v_revision ->> 'sourceBindingId' and
             s.superseded_by is null) then
        raise exception 'SOURCE_REVISION_OUTSIDE_PROJECT' using errcode = '22023';
      end if;
    else
      select count(*) into v_source_count from public.team_source_bindings s
        where s.workspace_id = p_workspace_id and
          s.project_key = v_revision ->> 'projectKey' and s.superseded_by is null;
      if v_source_count <> 1 then
        raise exception 'SOURCE_REVISION_AMBIGUOUS' using errcode = '22023';
      end if;
    end if;
  end loop;
end;
$$;
revoke all on function private.validate_team_revision_set(uuid,jsonb)
  from public, anon, authenticated;

create function private.guard_team_revision_set()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'UPDATE' and new.revision_set is not distinct from old.revision_set then
    return new;
  end if;
  perform private.validate_team_revision_set(new.workspace_id, new.revision_set);
  return new;
end;
$$;
revoke all on function private.guard_team_revision_set()
  from public, anon, authenticated;

create trigger guard_task_source_revisions before insert or update of revision_set
  on public.team_tasks for each row execute function private.guard_team_revision_set();
create trigger guard_evidence_source_revisions before insert or update of revision_set
  on public.team_evidence for each row execute function private.guard_team_revision_set();
create trigger guard_receipt_source_revisions before insert or update of revision_set
  on public.team_receipts for each row execute function private.guard_team_revision_set();

commit;

-- migration: 20261023032000_source_fact_partitions.sql
begin;

-- Source facts never enter the workspace-wide changes/snapshot feed. The
-- worker rechecks the caller's current repository grant on every read.
alter table public.team_source_bindings
  add constraint team_source_bindings_project_identity_unique unique(workspace_id, source_id, project_key);
create table public.team_source_fact_partitions (
  workspace_id uuid not null,
  project_key text not null,
  source_id text not null,
  revision_commit text not null check (revision_commit ~ '^[0-9a-f]{40}$'),
  path text not null check (char_length(path) between 1 and 500),
  analyzer_version text not null check (analyzer_version in ('openapi-json-v1','generated-client-v1')),
  content_hash text not null check (content_hash ~ '^[0-9a-f]{64}$'),
  fact_hash text not null check (fact_hash ~ '^[0-9a-f]{64}$'),
  facts jsonb not null check (jsonb_typeof(facts) = 'object' and octet_length(facts::text) <= 131072),
  indexed_at timestamptz not null default now(),
  primary key (workspace_id, source_id, revision_commit, path, analyzer_version),
  foreign key (workspace_id, source_id, project_key)
    references public.team_source_bindings(workspace_id, source_id, project_key) on delete cascade
);
create index team_source_facts_project_idx on public.team_source_fact_partitions(workspace_id, project_key, source_id, revision_commit);
alter table public.team_source_fact_partitions enable row level security;
revoke all on public.team_source_fact_partitions from public, anon, authenticated;
grant select, insert on public.team_source_fact_partitions to service_role;

-- Immutability makes a revision-pinned fact reusable across devices. A
-- mismatched re-analysis must be investigated rather than silently replacing
-- evidence already handed to another client.
create function private.reject_source_fact_change() returns trigger language plpgsql set search_path = '' as $$
begin
  raise exception 'SOURCE_FACT_IMMUTABLE' using errcode = '42501';
end $$;
revoke all on function private.reject_source_fact_change() from public;
create trigger source_fact_immutable before update on public.team_source_fact_partitions
  for each row execute function private.reject_source_fact_change();
commit;

-- migration: 20261023124345_deployment_cohort_control.sql
begin;

-- The protected controller is the only writer. Repository contributors and
-- ordinary workspace members cannot assert what is serving production.
create table public.team_deployment_environments (
  workspace_id uuid not null references public.team_workspaces(id) on delete cascade,
  environment_id text not null check(environment_id ~ '^[A-Za-z0-9_-]{1,80}$'),
  generation bigint not null default 0 check(generation >= 0),
  observed_at timestamptz,
  primary key(workspace_id, environment_id)
);
create table public.team_deployment_cohorts (
  workspace_id uuid not null,
  environment_id text not null,
  cohort_id text not null check(cohort_id ~ '^[A-Za-z0-9_-]{1,80}$'),
  project_key text not null,
  source_id text not null,
  revision_commit text not null check(revision_commit ~ '^[0-9a-f]{40}$'),
  artifact_digest text not null check(artifact_digest ~ '^sha256:[0-9a-f]{64}$'),
  active boolean not null,
  generation bigint not null check(generation > 0),
  observed_at timestamptz not null,
  primary key(workspace_id, environment_id, cohort_id),
  foreign key(workspace_id, environment_id) references public.team_deployment_environments(workspace_id, environment_id) on delete cascade,
  foreign key(workspace_id, source_id, project_key) references public.team_source_bindings(workspace_id, source_id, project_key)
);
create index team_deployment_cohorts_active_idx on public.team_deployment_cohorts(workspace_id, environment_id, project_key) where active;
create table public.team_deployment_events (
  event_id uuid primary key,
  workspace_id uuid not null,
  environment_id text not null,
  expected_generation bigint not null,
  accepted_generation bigint not null,
  controller_id text not null check(char_length(controller_id) between 1 and 120),
  payload jsonb not null check(jsonb_typeof(payload) = 'object' and octet_length(payload::text) <= 4000),
  received_at timestamptz not null default now(),
  foreign key(workspace_id, environment_id) references public.team_deployment_environments(workspace_id, environment_id) on delete cascade
);
create index team_deployment_events_scope_idx on public.team_deployment_events(workspace_id, environment_id, accepted_generation);

alter table public.team_deployment_environments enable row level security;
alter table public.team_deployment_cohorts enable row level security;
alter table public.team_deployment_events enable row level security;
revoke all on public.team_deployment_environments, public.team_deployment_cohorts, public.team_deployment_events from public, anon, authenticated;
grant select, insert, update on public.team_deployment_environments, public.team_deployment_cohorts to service_role;
grant select, insert on public.team_deployment_events to service_role;

create function public.apply_team_deployment_event(
  p_event_id uuid, p_workspace_id uuid, p_environment_id text,
  p_expected_generation bigint, p_controller_id text, p_payload jsonb
) returns jsonb language plpgsql set search_path = '' as $$
declare
  v_existing public.team_deployment_events%rowtype;
  v_generation bigint;
  v_project text := p_payload ->> 'projectKey';
  v_source text := p_payload ->> 'sourceBindingId';
  v_cohort text := p_payload ->> 'cohortId';
  v_revision text := p_payload ->> 'revision';
  v_artifact text := p_payload ->> 'artifactDigest';
  v_active boolean;
begin
  if current_user <> 'service_role' then raise exception 'DEPLOYMENT_CONTROLLER_REQUIRED' using errcode='42501'; end if;
  if coalesce(p_environment_id,'') !~ '^[A-Za-z0-9_-]{1,80}$' or
     char_length(coalesce(p_controller_id,'')) not between 1 and 120 or
     p_expected_generation is null or p_expected_generation < 0 or
     coalesce(jsonb_typeof(p_payload),'') <> 'object' or octet_length(p_payload::text) > 4000 or
     coalesce(v_project,'') !~ '^prj_[A-Za-z0-9_-]{4,100}$' or coalesce(v_source,'') !~ '^src_[A-Za-z0-9_-]{8,100}$' or
     coalesce(v_cohort,'') !~ '^[A-Za-z0-9_-]{1,80}$' or coalesce(v_revision,'') !~ '^[0-9a-f]{40}$' or
     coalesce(v_artifact,'') !~ '^sha256:[0-9a-f]{64}$' or coalesce(jsonb_typeof(p_payload -> 'active'),'') <> 'boolean' then
    raise exception 'INVALID_DEPLOYMENT_EVENT' using errcode='22023';
  end if;
  v_active := (p_payload ->> 'active')::boolean;
  if not exists(select 1 from public.team_source_bindings s
    where s.workspace_id=p_workspace_id and s.project_key=v_project and s.source_id=v_source
      and s.superseded_by is null) then
    raise exception 'DEPLOYMENT_SOURCE_UNAVAILABLE' using errcode='42501';
  end if;
  insert into public.team_deployment_environments(workspace_id,environment_id)
    values(p_workspace_id,p_environment_id) on conflict do nothing;
  select generation into v_generation from public.team_deployment_environments
    where workspace_id=p_workspace_id and environment_id=p_environment_id for update;
  select * into v_existing from public.team_deployment_events where event_id=p_event_id;
  if found then
    if v_existing.workspace_id<>p_workspace_id or v_existing.environment_id<>p_environment_id or
       v_existing.expected_generation<>p_expected_generation or v_existing.controller_id<>p_controller_id or
       v_existing.payload<>p_payload then
      raise exception 'DEPLOYMENT_EVENT_ID_REUSED' using errcode='40001';
    end if;
    return jsonb_build_object('eventId',p_event_id,'generation',v_existing.accepted_generation,'duplicate',true);
  end if;
  if v_generation <> p_expected_generation then raise exception 'DEPLOYMENT_GENERATION_CHANGED' using errcode='40001'; end if;
  if not v_active and not exists(select 1 from public.team_deployment_cohorts c
    where c.workspace_id=p_workspace_id and c.environment_id=p_environment_id and c.cohort_id=v_cohort
      and c.project_key=v_project and c.source_id=v_source and c.active) then
    raise exception 'ACTIVE_DEPLOYMENT_COHORT_REQUIRED' using errcode='40001';
  end if;
  update public.team_deployment_environments set generation=generation+1, observed_at=now()
    where workspace_id=p_workspace_id and environment_id=p_environment_id;
  if v_active then
    insert into public.team_deployment_cohorts(workspace_id,environment_id,cohort_id,project_key,source_id,
      revision_commit,artifact_digest,active,generation,observed_at)
    values(p_workspace_id,p_environment_id,v_cohort,v_project,v_source,v_revision,v_artifact,true,v_generation+1,now())
    on conflict(workspace_id,environment_id,cohort_id) do update
      set project_key=excluded.project_key,source_id=excluded.source_id,revision_commit=excluded.revision_commit,
          artifact_digest=excluded.artifact_digest,active=true,generation=excluded.generation,observed_at=excluded.observed_at;
  else
    update public.team_deployment_cohorts set active=false,generation=v_generation+1,observed_at=now()
      where workspace_id=p_workspace_id and environment_id=p_environment_id and cohort_id=v_cohort;
  end if;
  insert into public.team_deployment_events(event_id,workspace_id,environment_id,expected_generation,
    accepted_generation,controller_id,payload)
    values(p_event_id,p_workspace_id,p_environment_id,p_expected_generation,v_generation+1,p_controller_id,p_payload);
  return jsonb_build_object('eventId',p_event_id,'generation',v_generation+1,'duplicate',false);
end $$;
revoke all on function public.apply_team_deployment_event(uuid,uuid,text,bigint,text,jsonb) from public,anon,authenticated;
grant execute on function public.apply_team_deployment_event(uuid,uuid,text,bigint,text,jsonb) to service_role;
commit;
